import { useLocation } from 'react-router-dom';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import { QRScanOptions } from '~/entities/qr-scan/model/types';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';
import { useQRPaymentHandler } from './use-qr-scan-handler';

export const useQRScan = () => {
  const location = useLocation();
  const { navigate } = useNavigate();

  const [qrScanOptions, setQRScanOptions] = useStore(
    useShallow((state) => [state.qrScannerSlice.options, state.qrScannerSlice.setOptions]),
  );

  // QR 결제 처리를 위한 handler 호출
  useQRPaymentHandler();

  const openQRScanner = async (options: Omit<QRScanOptions, 'from'> & { from?: string }) => {
    setQRScanOptions({
      ...qrScanOptions,
      ...options,
      from: location.pathname,
    });
    navigate(PATHS.qrScan);
  };

  return {
    openQRScanner,
  };
};
