import { useErrorBoundary } from '@suspensive/react';
import { useEffect } from 'react';
import { useStore } from '~/app/store/store';
import { useTxSearchMutation } from '~/entities/exchange/api/hooks/use-tx-search-mutation';
import { useExchangeNavigation } from '~/entities/exchange/lib/use-exchange-navigation';
import { QRScanType } from '~/entities/qr-scan/model/types';
import { useGetShopListMutation } from '~/entities/shop/api/use-get-shop-list-mutation';
import { MPMQrScanType, TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';

const isPaymentQRType = (type: QRScanType | undefined) => {
  return type === QRScanType.QR_결제하기_결제금액포함 || type === QRScanType.QR_결제하기_결제금액없음;
};

export const useQRPaymentHandler = () => {
  const qrScanType = useStore((state) => state.qrScannerSlice.options.qrScanType);
  const scannedQRCode = useStore((state) => state.qrScannerSlice.QRCode);
  const isValid = useStore((state) => state.qrScannerSlice.isValid());
  const resetQRCodeState = useStore((state) => state.qrScannerSlice.resetQRCodeState);
  const { mutateAsync: txSearch } = useTxSearchMutation({ throwOnError: false });
  const { mutateAsync: getShopList } = useGetShopListMutation({ throwOnError: false });
  const { navigateToExchange, navigateToExchangeUseFixMpm } = useExchangeNavigation();
  const { setError } = useErrorBoundary();
  const { openAlertDialog } = useAlertDialog();

  useEffect(() => {
    if (!isValid || !isPaymentQRType(qrScanType)) return;

    const handleQRPayment = async () => {
      try {
        if (scannedQRCode.mpmType === MPMQrScanType.고정형) {
          openAlertDialog({
            message: i18n.t('moveToPaymentPage'),
            onConfirmClick: () => {
              navigateToExchangeUseFixMpm({
                payItem: {
                  aliasNm: scannedQRCode.aliasNm || '',
                  tokenId: '',
                  bankCode: scannedQRCode.bankCode || '',
                  placeId: scannedQRCode.placeId || '',
                  placeNm: scannedQRCode.placeNm || '',
                },
                mpmType: scannedQRCode.mpmType || '',
                aliasNm: scannedQRCode.aliasNm,
                walletInsttCd: scannedQRCode.bankCode,
                isAppToApp: false,
                isQrScan: true,
                trnscTypeCd: TrnscTypeCd.결제,
              });
            },
          });
          resetQRCodeState();
          return;
        }

        if (!scannedQRCode.txCode) {
          setError(new Error('txCode가 없습니다.'));
          return;
        }
        const result = await txSearch({ tbPayMastr: { txCd: scannedQRCode.txCode } });

        if (!result) {
          setError(new Error(i18n.t('validation:invalidTransactionNumber')));
          resetQRCodeState();
          return;
        }

        let placeNm = result.placeNm;
        if (!placeNm && result.placeId) {
          const shopList = await getShopList(result.placeId);
          if (shopList && shopList.length > 0) {
            placeNm = shopList.find((placeItem) => placeItem.placeId === result.placeId)?.placeNm ?? '';
          }
        }

        openAlertDialog({
          message: i18n.t('moveToPaymentPage'),
          onConfirmClick: () => {
            navigateToExchange({
              tbPayMastr: result,
              mpmType: scannedQRCode.mpmType || '',
              txCd: scannedQRCode.txCode,
              isAppToApp: false,
              isQrScan: true,
              trnscTypeCd: TrnscTypeCd.결제,
              placeNm,
            });
          },
        });

        resetQRCodeState();
      } catch {
        setError(new Error(i18n.t('validation:invalidTransactionNumber')));
        resetQRCodeState();
      }
    };

    handleQRPayment();
  }, [isValid, qrScanType, scannedQRCode]);
};
